 <script>
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const state={player:{x:.5,y:.59,hp:420,max:420,spd:.26,dir:1,inv:0},enemy:{x:.65,y:.47,hp:620,max:620,name:'Brambleback',alive:true,elem:null,stacks:0,status:[],resist:1.15},party:[{name:'Mosskin',kind:'moss',icon:'❋',element:'TERRA',hp:180,max:180},{name:'Cindertail',kind:'fox',icon:'♨',element:'FLAME',hp:155,max:155},{name:'Glimmerwing',kind:'moth',icon:'✧',element:'GALE',hp:145,max:145}],class:'Riftwarden',sync:34,shards:120,materials:{'Bramble Scale':0,'Aether Bone':0,'Wild Core':0},gear:[],time:0,last:0,attackCd:0,abilityCd:0,captureCd:0,enemyAttack:0,blink:0,particles:[],floating:[],keys:{},invuln:0,round:1,feed:[],selected:0,combo:null,won:false,dead:false};
+const classData={Riftwarden:{art:'Aegis Break',desc:'Shielded arc · 28 dmg',icon:'◈',skill:'Aegis',element:'TERRA',damage:28},Elementalist:{art:'Prismatic Surge',desc:'Arcane bolt · 38 dmg',icon:'✧',skill:'Surge',element:'FLAME',damage:38},Shadowdancer:{art:'Umbral Flurry',desc:'Rapid strike · 34 dmg',icon:'◌',skill:'Flurry',element:'GALE',damage:34},Animist:{art:'Verdant Mend',desc:'Mend & thorn · 22 dmg',icon:'❋',skill:'Mend',element:'TIDE',damage:22}};
+const combos={'FLAME+TIDE':{name:'Steam Burst',desc:'Scalding AoE · blinds target (-40% accuracy)',color:'#ffbb8b'},'GALE+FLAME':{name:'Wildfire Whirlwind',desc:'Spreads burning damage to adjacent foes',color:'#ff9c6e'},'TERRA+TIDE':{name:'Mudslide Quake',desc:'Roots target · physical defense -30%',color:'#b8b994'},'TERRA+GALE':{name:'Dust Storm',desc:'Accuracy down · weak points exposed for 8s',color:'#d6c78c'}};
+const $=id=>document.getElementById(id);let W=0,H=0,dpr=1;
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(resize).observe(canvas);resize();
+function notify(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),2100)}
+function log(msg){state.feed.unshift(msg);state.feed.length=Math.min(3,state.feed.length);$('feed').innerHTML=state.feed.map(x=>`<span>✦ ${x}</span>`).join('')}
+function refresh(){const p=state.player,e=state.enemy; $('playerHpText').textContent=`${Math.ceil(p.hp)} / ${p.max}`;$('leaderHpText').textContent=`${Math.ceil(p.hp)} / ${p.max}`;$('playerBar').style.width=`${p.hp/p.max*100}%`;$('leaderBar').style.width=`${p.hp/p.max*100}%`;$('enemyBar').style.width=`${Math.max(0,e.hp/e.max*100)}%`;$('targetHpBar').style.width=`${Math.max(0,e.hp/e.max*100)}%`;$('enemyHpText').textContent=`${Math.max(0,Math.ceil(e.hp/e.max*100))}%`;$('syncText').textContent=`${Math.floor(state.sync)}%`;$('syncBar').style.width=`${state.sync}%`;$('shards').textContent=state.shards;
+$('enemyName').textContent=e.alive?`${e.name.toUpperCase()} · WILD`:state.won?'RIFT HEART · DORMANT':'WILD ESSENCE';$('targetName').textContent=e.alive?e.name:state.won?'Rift Heart':'Wild Essence';$('enemyMeta').textContent=e.alive?'TERRA / BEAST · LV 06':state.won?'RIFT CLEARED':'HARVEST READY';$('enemyStatus').textContent=e.alive?e.status.map(s=>s.toUpperCase()).join(' · '):'';$('waveText').textContent=state.won?'RIFT STABILIZED':e.hp<e.max*.15?'CAPTURE WINDOW OPEN':'RIFT ACTIVITY · LOW';$('captureBtn').disabled=!e.alive||e.hp/e.max>=.15;$('captureBtn').style.opacity=$('captureBtn').disabled?'.45':'1';$('className').textContent=`${state.class.toUpperCase()} · LV 08`;const cd=classData[state.class];$('artOne').innerHTML=`${cd.art} <span class="key">Q</span>`;$('artOneDesc').textContent=cd.desc;$('skillIcon').textContent=cd.icon;$('skillName').textContent=cd.skill;$('unisonDesc').textContent=state.sync>=100?'READY · unleash together':`Requires ${Math.ceil(100-state.sync)}% more bond`;$('unisonButton').classList.toggle('disabled',state.sync<100);$('partyList').innerHTML=state.party.map((m,i)=>`<div class="unit ${i===state.selected?'active':''}"><div class="unit-icon">${m.icon}</div><div class="unit-detail"><strong>${m.name}</strong><span>${m.element} · LV 06</span></div><div class="unit-hp">${Math.ceil(m.hp)}/${m.max}</div></div>`).join('')}
+function addParticle(x,y,color,n=12){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=30+Math.random()*110;state.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+Math.random()*.55,color,size:2+Math.random()*4})}}
+function floatText(x,y,text,color='#fff'){state.floating.push({x,y,text,color,life:1})}
+function combo(first,second){let k=[first,second].sort().join('+'); // map only valid pair strings
+if(first==='FLAME'&&second==='TIDE'||first==='TIDE'&&second==='FLAME')k='FLAME+TIDE';else if(first==='GALE'&&second==='FLAME'||first==='FLAME'&&second==='GALE')k='GALE+FLAME';else if(first==='TERRA'&&second==='TIDE'||first==='TIDE'&&second==='TERRA')k='TERRA+TIDE';else if(first==='TERRA'&&second==='GALE'||first==='GALE'&&second==='TERRA')k='TERRA+GALE';else return null;return combos[k]}
+function react(element){const e=state.enemy;if(!e.alive)return;let reaction=null;if(e.elem&&e.elem!==element)reaction=combo(e.elem,element);if(reaction){state.combo=reaction; $('reactionName').textContent=reaction.name;$('reactionDesc').textContent=reaction.desc;$('reactionName').style.color=reaction.color;floatText(W*e.x,H*e.y-50,reaction.name,reaction.color);addParticle(W*e.x,H*e.y,reaction.color,30);e.status.push(reaction.name);damage(78,reaction.name);if(reaction.name==='Wildfire Whirlwind')e.status.push('Burning');if(reaction.name==='Mudslide Quake')e.status.push('Rooted');if(reaction.name==='Steam Burst'||reaction.name==='Dust Storm')e.status.push('Blinded');log(`${reaction.name} reaction!`);state.sync=Math.min(100,state.sync+13);e.elem=null;e.stacks=0}else{e.elem=element;e.stacks++;if(e.stacks>=2)e.elem=null;}}
+function damage(amount,source='Strike'){const e=state.enemy;if(!e.alive)return;e.hp=Math.max(0,e.hp-amount);floatText(W*e.x,H*e.y-22,`−${Math.round(amount)}`,'#ffd3b1');addParticle(W*e.x,H*e.y,'#f2a480',8);state.sync=Math.min(100,state.sync+1.6);if(e.hp<=0)defeat()}
+function defeat(){state.enemy.alive=false;state.won=true;state.shards+=45;state.materials['Bramble Scale']+=2;state.materials['Aether Bone']+=1;state.materials['Wild Core']+=1;log('Brambleback felled · wild essence harvested');notify('Rift guardian defeated · +45 shards');$('objective-card');$('objective-card')&&($('objective-card').innerHTML='<strong>Directive Complete</strong><p><span class="step">✓</span> · Guardian subdued or slain<br><span class="step">✓</span> · Wild essence harvested<br><span class="step">03</span> · Enter the rift to claim your reward</p>');refresh()}
+function strike(){if(state.attackCd>0)return;state.attackCd=.42;const p=state.player,e=state.enemy;if(!e.alive){notify('No hostile target in range.');return}const dx=e.x-p.x,dy=e.y-p.y;if(Math.hypot(dx,dy)>.43){notify('Move closer to strike.');return}p.dir=dx>=0?1:-1;damage(20+Math.random()*8);react('TERRA');log('Kael strikes with a warding blade');}
+function ability(){if(state.abilityCd>0)return;const e=state.enemy;if(!e.alive){notify('The grove is quiet.');return}state.abilityCd=4.5;const c=classData[state.class];if(state.class==='Animist'){state.player.hp=Math.min(state.player.max,state.player.hp+52);state.party.forEach(x=>x.hp=Math.min(x.max,x.hp+28));notify('Verdant Mend restores the frontline');}damage(c.damage,c.art);react(c.element);if(state.class==='Riftwarden'){state.player.invuln=1.2;state.player.hp=Math.min(state.player.max,state.player.hp+16)}if(state.class==='Shadowdancer'){state.player.invuln=.7;damage(15,'Flurry')}if(state.class==='Elementalist')addParticle(W*e.x,H*e.y,'#a991ff',28);log(`${c.art} unleashed`);refresh()}
+function capture(){const e=state.enemy;if(!e.alive){notify('There is no wild creature to bind.');return}if(e.hp/e.max>=.15){notify('Weaken the guardian below 15% vitality first.');return}if(state.captureCd>0){notify('The snare is still recharging.');return}state.captureCd=2.2;const status=e.status.length?1.55:1,gear=state.gear.includes('Frostbound Grips')?1.35:1,bait=state.bait?1.35:1,trap=state.trap?1.5:1;const base=.68,prob=Math.min(.98,((1-e.hp/e.max)*base*status*gear*bait*trap)/e.resist);if(Math.random()<prob){e.hp=0;state.party.push({name:'Brambleback',kind:'beast',icon:'♧',element:'TERRA',hp:210,max:210});state.sync=Math.min(100,state.sync+18);log(`Aether-snare bound Brambleback · ${Math.round(prob*100)}% chance`);notify('Brambleback bonded · joins your frontline');defeat()}else{state.player.hp=Math.max(1,state.player.hp-18);addParticle(W*e.x,H*e.y,'#a78dff',15);notify(`Tether resisted · ${Math.round(prob*100)}% capture chance`);log('Aether-snare tether resisted');refresh()}}
+function unison(){if(state.sync<100){notify('Unison requires 100% Sync Rate. Fight together to bond.');return}if(!state.enemy.alive)return;state.sync=0;damage(175,'Unison');state.party.forEach(m=>{m.hp=Math.min(m.max,m.hp+40)});state.player.hp=Math.min(state.player.max,state.player.hp+30);addParticle(W*state.enemy.x,H*state.enemy.y,'#c7a2ff',50);log('UNISON ULTIMATE · Echoes converge');notify('UNISON ULTIMATE · Riftbreaker!');refresh()}

