function unison(){if(state.sync<100){notify('Unison requires 100% Sync Rate. Fight together to bond.');return}if(!state.enemy.alive)return;state.sync=0;damage(175,'Unison');state.party.forEach(m=>{m.hp=Math.min(m.max,m.hp+40)});state.player.hp=Math.min(state.player.max,state.player.hp+30);addParticle(W*state.enemy.x,H*state.enemy.y,'#c7a2ff',50);log('UNISON ULTIMATE · Echoes converge');notify('UNISON ULTIMATE · Riftbreaker!');refresh()}
function dodge(){if(state.player.invuln>0)return;state.player.invuln=.7;state.player.x=Math.min(.91,Math.max(.09,state.player.x+state.player.dir*.085));addParticle(W*state.player.x,H*state.player.y,'#80e5db',10)}
function doAction(a){if(a==='attack')strike();if(a==='ability')ability();if(a==='capture')capture();if(a==='dodge')dodge();if(a==='unison')unison()}
function openModal(title,subtitle,items){$('modalTitle').textContent=title;$('modalSubtitle').textContent=subtitle;$('modalContent').innerHTML=items.map(x=>`<div class="modal-item"><h3>${x.icon||'✧'} ${x.name}</h3><p>${x.desc}</p>${x.button?`<button data-modal-action="${x.action}">${x.button}</button>`:''}</div>`).join('');$('modalWrap').classList.add('open');$('modalContent').querySelectorAll('[data-modal-action]').forEach(b=>b.onclick=()=>modalAction(b.dataset.modalAction))}
function modalAction(a){if(a==='class'){const cls=event.currentTarget.dataset.class;state.class=cls;$('className').textContent=`${cls.toUpperCase()} · LV 08`;const d=classData[cls];$('artOne').innerHTML=`${d.art} <span class="key">Q</span>`;$('artOneDesc').textContent=d.desc;$('skillIcon').textContent=d.icon;$('skillName').textContent=d.skill;notify(`${cls} class selected`);refresh();return}if(a==='frost'){if(state.shards<60){notify('Not enough shards.');return}state.shards-=60;state.gear.push('Frostbound Grips');notify('Frostbound Grips forged · capture chance increased');refresh();return}if(a==='bait'){if(state.shards<25){notify('Not enough shards.');return}state.shards-=25;state.bait=true;notify('Lumen bait ready · capture chance increased');refresh();return}if(a==='trap'){if(state.shards<35){notify('Not enough shards.');return}state.shards-=35;state.trap=true;notify('Snare trap deployed · capture chance increased');refresh();return}if(a==='weapon'){if(state.materials['Bramble Scale']<2||state.materials['Aether Bone']<1){notify('Harvest 2 scales and 1 bone first.');return}if(state.gear.includes('Bramblethorn Edge')){notify('Bramblethorn Edge already forged.');return}state.materials['Bramble Scale']-=2;state.materials['Aether Bone']--;state.gear.push('Bramblethorn Edge');notify('Bramblethorn Edge forged · strike damage +12');}
refresh()}
function partyModal(){openModal('Frontline & Vows','Choose a discipline. Switching class changes your signature art and combat element.',Object.entries(classData).map(([name,d])=>({name,icon:d.icon,desc:`${name==='Riftwarden'?'Bulwark tank':name==='Elementalist'?'Elemental caster':name==='Shadowdancer'?'Agile striker':'Spirit support'} · ${d.element} · ${d.desc}`,button:state.class===name?'SELECTED':'Choose class',action:'class',class:name})));$('modalContent').querySelectorAll('[data-modal-action="class"]').forEach((b,i)=>b.dataset.class=Object.keys(classData)[i])}
function forgeModal(){openModal('The Aether Forge','Use shards and harvested essence to prepare for deeper rifts.',[{name:'Bramblethorn Edge',icon:'⚔',desc:`Monster-forged blade · strike damage +12. Cost: 2 Bramble Scales, 1 Aether Bone. In stock: ${state.materials['Bramble Scale']} scales · ${state.materials['Aether Bone']} bones.`,button:state.gear.includes('Bramblethorn Edge')?'FORGED':'Forge weapon',action:'weapon'},{name:'Frostbound Grips',icon:'❄',desc:'Cold-forged bindings amplify Aether-Snare capture chance by 35%. Cost: 60 shards.',button:state.gear.includes('Frostbound Grips')?'EQUIPPED':'Forge · 60 ◈',action:'frost'},{name:'Lumen Bait',icon:'❋',desc:'Lure wild creatures into a calm state. Next snare gains +35% capture chance. Cost: 25 shards.',button:state.bait?'READY':'Prepare · 25 ◈',action:'bait'},{name:'Aether Trap',icon:'⌁',desc:'Prime the clearing with a binding sigil. Next snare gains +50% capture chance. Cost: 35 shards.',button:state.trap?'DEPLOYED':'Set trap · 35 ◈',action:'trap'}])}
function enterRift(){if(!state.won){notify('Subdue or slay the guardian before entering.');return}state.round++;state.won=false;state.enemy={x:.65,y:.47,hp:740+state.round*65,max:740+state.round*65,name:state.round%2?'Rift-Touched Stag':'Hollowmaw',alive:true,elem:null,stacks:0,status:[],resist:1.05+state.round*.04};state.player.hp=Math.min(state.player.max,state.player.hp+95);state.party.forEach(m=>m.hp=Math.min(m.max,m.hp+60));$('waveText').textContent=`RIFT ${String(state.round).padStart(2,'0')} · DEEPENING`;$('enemyMeta').textContent='TERRA / ABERRANT · LV 08';$('targetName').textContent=state.enemy.name;$('objective-card');log(`Rift ${state.round} breached · threat escalating`);notify(`Rift depth ${state.round} · new guardian detected`);refresh()}
function keyDown(e){if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();state.keys[e.key.toLowerCase()]=true;if(e.repeat)return;if(e.key===' ')strike();if(e.key.toLowerCase()==='q')ability();if(e.key.toLowerCase()==='e')capture();if(e.key.toLowerCase()==='r')unison();if(e.key==='Shift')dodge();if(e.key.toLowerCase()==='f')forgeModal();if(e.key>='1'&&e.key<='3')state.selected=Number(e.key)-1;}
window.addEventListener('keydown',keyDown);window.addEventListener('keyup',e=>state.keys[e.key.toLowerCase()]=false);
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>doAction(b.dataset.action)));document.querySelectorAll('[data-move]').forEach(b=>{const move=()=>{const d=b.dataset.move;state.keys[d==='up'?'w':d==='down'?'s':d==='left'?'a':'d']=true};b.addEventListener('pointerdown',move);['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>{const d=b.dataset.move;state.keys[d==='up'?'w':d==='down'?'s':d==='left'?'a':'d']=false}))});$('partyBtn').onclick=partyModal;$('craftBtn').onclick=forgeModal;$('captureBtn').onclick=capture;$('riftBtn').onclick=enterRift;$('closeModal').onclick=()=>$('modalWrap').classList.remove('open');$('modalWrap').addEventListener('click',e=>{if(e.target===$('modalWrap'))$('modalWrap').classList.remove('open')});

